'use strict';
let rehearsal=null,rehearsalRAF=0,rehearsalContext=null,rehearsalSource=null;
document.querySelector('.studio-toolbar').insertAdjacentHTML('beforeend','<button id="openSceneRehearsal">Rehearse story</button>');
$('previewConversation').after(Object.assign(document.createElement('button'),{id:'rehearseFromScript',textContent:'Rehearse storyboard'}));
document.body.insertAdjacentHTML('beforeend','<dialog id="sceneRehearsalDialog"><div class="tool-heading"><div><div class="eyebrow">LISTEN BEFORE DETAILED ANIMATION</div><h2>Story rehearsal</h2></div><button id="closeSceneRehearsal">Done</button></div><div class="ease-two-col"><div><canvas id="sceneRehearsalCanvas" width="640" height="360" aria-label="Timed storyboard rehearsal"></canvas><div class="rig-tools"><button id="playSceneRehearsal">Play</button><button id="rehearsalPrevious">Previous scene</button><button id="rehearsalNext">Next scene</button><span id="rehearsalClock"></span></div><input id="sceneRehearsalTime" type="range" min="0" max="6" step="0.01" aria-label="Story rehearsal time"><h3 id="rehearsalSceneName"></h3><p id="rehearsalSpokenLine" class="rehearsal-spoken"></p><p class="note">Opening storyboard frames play with the existing timeline audio. This is a timing rehearsal, so detailed character motion stays still.</p></div><aside><div id="rehearsalSceneList" class="ease-card-list"></div><label>Notes for this scene<textarea id="rehearsalNotes" rows="5" maxlength="4000" placeholder="Pacing, dialogue or staging changes…"></textarea></label><button id="rehearsalEditScene">Open this scene in editor</button><button id="downloadRehearsalNotes">Save review notes</button><p id="rehearsalStatus" role="status" class="note"></p></aside></div></dialog>');
function rehearsalSceneAt(at){let offset=0;for(let i=0;i<rehearsal.project.scenes.length;i++){const s=rehearsal.project.scenes[i];if(at<offset+s.duration||i===rehearsal.project.scenes.length-1)return{scene:s,index:i,offset,local:clamp(at-offset,0,s.duration)};offset+=s.duration}}
function commitRehearsalNotes(){if(!rehearsal||project!==rehearsal.project)return;const s=rehearsal.project.scenes.find(s=>s.id===$('rehearsalNotes').dataset.scene);if(s&&s.rehearsalNotes!==$('rehearsalNotes').value){s.rehearsalNotes=$('rehearsalNotes').value;save()}}
function paintRehearsal(){if(!rehearsal)return;const {scene:s,index,local}=rehearsalSceneAt(rehearsal.at),canvas=$('sceneRehearsalCanvas'),g=canvas.getContext('2d');if($('rehearsalNotes').dataset.scene!==s.id){commitRehearsalNotes();$('rehearsalNotes').dataset.scene=s.id;$('rehearsalNotes').value=s.rehearsalNotes||''}g.fillStyle='#101115';g.fillRect(0,0,640,360);const frame=rehearsal.frames[index];if(frame)g.drawImage(frame,0,0);$('rehearsalSceneName').textContent=(index+1)+' · '+s.name;const active=storyLines(s).filter(l=>local>=l.start&&local<l.start+l.duration);$('rehearsalSpokenLine').textContent=active.length?active.map(l=>actorName(s,l.speakerId)+': '+l.text).join('\n'):' ';$('sceneRehearsalTime').value=rehearsal.at;$('rehearsalClock').textContent=rehearsal.at.toFixed(1)+' / '+rehearsal.duration.toFixed(1)+'s';document.querySelectorAll('[data-rehearsal-scene]').forEach(b=>b.classList.toggle('active',+b.dataset.rehearsalScene===index));$('playSceneRehearsal').textContent=rehearsal.playing?'Pause':'Play'}
function stopRehearsalAudio(){cancelAnimationFrame(rehearsalRAF);try{rehearsalSource?.stop()}catch{}rehearsalSource=null;if(rehearsal)rehearsal.playing=false}
async function playRehearsal(){if(!rehearsal?.ready)return;if(rehearsal.playing){rehearsal.at=Math.min(rehearsal.duration,rehearsal.startAt+(performance.now()-rehearsal.started)/1000);stopRehearsalAudio();paintRehearsal();return}const session=rehearsal;try{if(session.at>=session.duration-.01)session.at=0;if(session.mix){rehearsalContext??=new AudioContext();await rehearsalContext.resume();if(rehearsal!==session)return;rehearsalSource=rehearsalContext.createBufferSource();rehearsalSource.buffer=session.mix;rehearsalSource.connect(rehearsalContext.destination);rehearsalSource.start(0,Math.min(session.at,session.mix.duration))}session.startAt=session.at;session.started=performance.now();session.playing=true;function frame(){if(rehearsal!==session||!session.playing)return;session.at=Math.min(session.duration,session.startAt+(performance.now()-session.started)/1000);paintRehearsal();if(session.at>=session.duration){stopRehearsalAudio();paintRehearsal()}else rehearsalRAF=requestAnimationFrame(frame)}frame()}catch(e){stopRehearsalAudio();$('rehearsalStatus').textContent=e.message}}
function seekRehearsal(at){if(!rehearsal?.ready)return;const resume=rehearsal.playing;stopRehearsalAudio();rehearsal.at=clamp(at,0,rehearsal.duration);paintRehearsal();if(resume)playRehearsal()}
async function openSceneRehearsal(){if(recording||audioBusy||speechProcessing||storyProcessing)return toast('Finish the current media task first.');stop();if($('storyToolsDialog').open)$('storyToolsDialog').close();const session={project,at:sceneOffset()+time,duration:totalDuration(),frames:[],ready:false,playing:false};rehearsal=session;window.editorTaskBusy=true;delete $('rehearsalNotes').dataset.scene;$('rehearsalNotes').value='';$('sceneRehearsalTime').max=session.duration;$('rehearsalStatus').textContent='Preparing local storyboard frames and audio…';$('playSceneRehearsal').disabled=true;$('sceneRehearsalDialog').showModal();try{const view=projectView(),list=$('rehearsalSceneList');list.replaceChildren();let offset=0;for(const [i,s]of project.scenes.entries()){await preloadProductionAssets(s);if(rehearsal!==session)return;for(const o of s.objects.filter(o=>o.type==='video'))await seekVideo(videoFor(o),o.sourceOffset||0);const source=document.createElement('canvas');source.width=960;source.height=540;renderSceneFrame(source.getContext('2d'),s,Math.min(.05,s.duration));const c=document.createElement('canvas');c.width=640;c.height=360;const ctx=c.getContext('2d'),scale=Math.min(640/view.width,360/view.height),w=view.width*scale,h=view.height*scale;ctx.fillStyle='#101115';ctx.fillRect(0,0,640,360);ctx.drawImage(source,view.left,0,view.width,view.height,(640-w)/2,(360-h)/2,w,h);session.frames.push(c);const at=offset,b=storyButton((i+1)+' · '+s.name+' · '+s.duration.toFixed(1)+'s',()=>seekRehearsal(at));b.dataset.rehearsalScene=i;list.append(b);offset+=s.duration}if(tracks().length||narrationBuffer||musicBuffer)session.mix=await mixedAudio();if(rehearsal!==session)return;session.ready=true;$('playSceneRehearsal').disabled=false;const unattached=project.scenes.flatMap(storyLines).filter(l=>l.text.trim()&&!l.audioId).length,unarranged=project.scenes.filter(s=>storyLines(s).length&&!s.dialogueArranged).length;$('rehearsalStatus').textContent=[unattached?unattached+' lines have no voice recording.':'',unarranged?unarranged+' scenes have unarranged dialogue. Arrange voices in Script to synchronize the rehearsal.':'','Ready. Notes save with the project.'].filter(Boolean).join(' ');paintRehearsal()}catch(e){$('rehearsalStatus').textContent=e.message}}
$('openSceneRehearsal').onclick=openSceneRehearsal;$('rehearseFromScript').onclick=openSceneRehearsal;$('playSceneRehearsal').onclick=playRehearsal;$('sceneRehearsalTime').oninput=e=>seekRehearsal(+e.target.value);$('rehearsalNotes').onchange=commitRehearsalNotes;
for(const[id,delta]of[['rehearsalPrevious',-1],['rehearsalNext',1]])$(id).onclick=()=>{if(!rehearsal?.ready)return;const current=rehearsalSceneAt(rehearsal.at),i=clamp(current.index+delta,0,project.scenes.length-1),at=project.scenes.slice(0,i).reduce((n,s)=>n+s.duration,0);seekRehearsal(at)};
$('closeSceneRehearsal').onclick=()=>$('sceneRehearsalDialog').close();$('sceneRehearsalDialog').addEventListener('close',()=>{commitRehearsalNotes();stopRehearsalAudio();rehearsal=null;window.editorTaskBusy=false;pauseVideoMedia();if(rehearsalContext){rehearsalContext.close().catch(()=>{});rehearsalContext=null}render()});
$('rehearsalEditScene').onclick=()=>{if(!rehearsal?.ready)return;const {index,local}=rehearsalSceneAt(rehearsal.at);$('sceneRehearsalDialog').close();sceneIndex=index;time=local;selectLayers([]);render()};
$('downloadRehearsalNotes').onclick=()=>{if(!rehearsal?.ready)return;commitRehearsalNotes();const text=project.scenes.map((s,i)=>(i+1)+'. '+s.name+' ('+s.duration.toFixed(1)+'s)\n'+(s.rehearsalNotes||'No notes.')).join('\n\n');download(new Blob([text],{type:'text/plain'}),'story-review-notes.txt')};
const validBeforeRehearsal=valid;valid=function(p){return validBeforeRehearsal(p)&&p.scenes.every(s=>s.rehearsalNotes===undefined||typeof s.rehearsalNotes==='string'&&s.rehearsalNotes.length<=4000)};
